INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-13-01', 'lesson-essential-verbs-a1-13', 1, 'sentence', 'I try to read every day.', 'Eu tento ler todo dia.', '/aɪ traɪ tuː riːd ˈɛvri deɪ/', '"Try to" + verbo = tentar. "Try" + substantivo = experimentar: "try the soup".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"read","pos":"verb","ipa":"/riːd/","gloss":"ler"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-13-02', 'lesson-essential-verbs-a1-13', 2, 'sentence', 'She tried the local food.', 'Ela experimentou a comida local.', '/ʃiː traɪd ðə ˈloʊkəl fuːd/', 'Passado regular com troca de "y" por "i": try → tried.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"tried","pos":"verb","ipa":"/traɪd/","gloss":"tentou, experimentou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"local","pos":"adjective","ipa":"/ˈloʊkəl/","gloss":"local"},{"surface":"food","pos":"noun","ipa":"/fuːd/","gloss":"comida"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-13-03', 'lesson-essential-verbs-a1-13', 3, 'sentence', 'I''ll try again tomorrow.', 'Vou tentar de novo amanhã.', '/aɪl traɪ əˈɡɛn təˈmɑːroʊ/', 'Futuro com "will". "Again" = de novo.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-13-04', 'lesson-essential-verbs-a1-13', 4, 'sentence', 'Have you tried this app?', 'Você já experimentou este aplicativo?', '/hæv juː traɪd ðɪs æp/', 'Present perfect para experiência: "Have you ever tried…?".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tried","pos":"verb","ipa":"/traɪd/","gloss":"tentou, experimentou"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"app","pos":"noun","ipa":"/æp/","gloss":"aplicativo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-13-05', 'lesson-essential-verbs-a1-13', 5, 'sentence', 'Can I ask you a question?', 'Posso te fazer uma pergunta?', '/kæn aɪ æsk juː ə ˈkwɛstʃən/', '"Ask a question" = fazer uma pergunta (nunca "make a question").', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"ask","pos":"verb","ipa":"/æsk/","gloss":"perguntar, pedir"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","gloss":"pergunta"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-13-06', 'lesson-essential-verbs-a1-13', 6, 'sentence', 'He asked for the check.', 'Ele pediu a conta.', '/hiː æskt fɔːr ðə tʃɛk/', '"Ask for" + coisa = pedir. Passado regular: "asked" (/æskt/).', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-13-07', 'lesson-essential-verbs-a1-13', 7, 'sentence', 'I will ask my manager.', 'Vou perguntar ao meu gerente.', '/aɪ wɪl æsk maɪ ˈmænɪdʒər/', '"Ask" + pessoa, sem preposição: "ask my manager".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"ask","pos":"verb","ipa":"/æsk/","gloss":"perguntar, pedir"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-13-08', 'lesson-essential-verbs-a1-13', 8, 'sentence', 'Nobody has asked me that before.', 'Ninguém nunca me perguntou isso antes.', '/ˈnoʊbɑːdi hæz æskt miː ðæt bɪˈfɔːr/', '"Nobody" já é negativo; o verbo fica afirmativo: "has asked".', '[]'::jsonb, '[{"surface":"Nobody","pos":"pronoun","ipa":"/ˈnoʊbɑːdi/","gloss":"ninguém"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-14-01', 'lesson-essential-verbs-a1-14', 1, 'sentence', 'I need a break.', 'Preciso de uma pausa.', '/aɪ niːd ə breɪk/', '"Need" + substantivo, ou "need to" + verbo: "I need to rest".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"break","pos":"noun","ipa":"/breɪk/","gloss":"pausa, intervalo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-14-02', 'lesson-essential-verbs-a1-14', 2, 'sentence', 'We needed more time.', 'Precisávamos de mais tempo.', '/wiː ˈniːdɪd mɔːr taɪm/', 'Passado regular: "needed" (/ɪd/ depois de "d").', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"needed","pos":"verb","ipa":"/ˈniːdɪd/","gloss":"precisou"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-14-03', 'lesson-essential-verbs-a1-14', 3, 'sentence', 'You won''t need a jacket.', 'Você não vai precisar de jaqueta.', '/juː woʊnt niːd ə ˈdʒækɪt/', 'Futuro negativo: "won''t" + verbo base.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"won''t","pos":"modal verb","ipa":"/woʊnt/","gloss":"não vai (will not)"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"jacket","pos":"noun","ipa":"/ˈdʒækɪt/","gloss":"jaqueta"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-14-04', 'lesson-essential-verbs-a1-14', 4, 'sentence', 'I''ve needed glasses since I was a kid.', 'Uso óculos desde criança.', '/aɪv ˈniːdɪd ˈɡlæsɪz sɪns aɪ wɑːz ə kɪd/', 'Present perfect + "since": situação que continua até hoje.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"needed","pos":"verb","ipa":"/ˈniːdɪd/","gloss":"precisou"},{"surface":"glasses","pos":"noun","ipa":"/ˈɡlæsɪz/","gloss":"óculos"},{"surface":"since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"kid","pos":"noun","ipa":"/kɪd/","gloss":"criança"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-14-05', 'lesson-essential-verbs-a1-14', 5, 'sentence', 'I feel much better today.', 'Estou me sentindo muito melhor hoje.', '/aɪ fiːl mʌtʃ ˈbɛtər təˈdeɪ/', '"Feel" + adjetivo. "Much better" = muito melhor.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-14-06', 'lesson-essential-verbs-a1-14', 6, 'sentence', 'She felt sick after the trip.', 'Ela se sentiu mal depois da viagem.', '/ʃiː fɛlt sɪk ˈæftər ðə trɪp/', 'Passado irregular: "felt". "Sick" = doente, enjoado.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"felt","pos":"verb","ipa":"/fɛlt/","gloss":"sentiu"},{"surface":"sick","pos":"adjective","ipa":"/sɪk/","gloss":"doente, enjoado"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-14-07', 'lesson-essential-verbs-a1-14', 7, 'sentence', 'You will feel at home here.', 'Você vai se sentir em casa aqui.', '/juː wɪl fiːl æt hoʊm hɪr/', '"Feel at home" = sentir-se em casa. Futuro com "will".', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-14-08', 'lesson-essential-verbs-a1-14', 8, 'sentence', 'Have you ever felt this way?', 'Você já se sentiu assim?', '/hæv juː ˈɛvər fɛlt ðɪs weɪ/', 'Present perfect + "ever" em pergunta sobre experiência.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"ever","pos":"adverb","ipa":"/ˈɛvər/","gloss":"alguma vez, já"},{"surface":"felt","pos":"verb","ipa":"/fɛlt/","gloss":"sentiu"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-15-01', 'lesson-essential-verbs-a1-15', 1, 'sentence', 'It becomes cold in the evening.', 'Fica frio à noite.', '/ɪt bɪˈkʌmz koʊld ɪn ðə ˈiːvnɪŋ/', '"Become" + adjetivo = tornar-se, ficar (mais formal que "get").', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"becomes","pos":"verb","ipa":"/bɪˈkʌmz/","gloss":"torna-se, fica"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"evening","pos":"noun","ipa":"/ˈiːvnɪŋ/","gloss":"noite (início), fim de tarde"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-15-02', 'lesson-essential-verbs-a1-15', 2, 'sentence', 'She became a doctor.', 'Ela se tornou médica.', '/ʃiː bɪˈkeɪm ə ˈdɑːktər/', 'Passado irregular: "became". Profissão com "a/an".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"became","pos":"verb","ipa":"/bɪˈkeɪm/","gloss":"tornou-se"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"doctor","pos":"noun","ipa":"/ˈdɑːktər/","gloss":"médico"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-15-03', 'lesson-essential-verbs-a1-15', 3, 'sentence', 'He will become a great teacher.', 'Ele vai se tornar um ótimo professor.', '/hiː wɪl bɪˈkʌm ə ɡreɪt ˈtiːtʃər/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"become","pos":"verb","ipa":"/bɪˈkʌm/","gloss":"tornar-se"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"great","pos":"adjective","ipa":"/ɡreɪt/","gloss":"ótimo"},{"surface":"teacher","pos":"noun","ipa":"/ˈtiːtʃər/","gloss":"professor, professora"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-15-04', 'lesson-essential-verbs-a1-15', 4, 'sentence', 'The city has become very expensive.', 'A cidade ficou muito cara.', '/ðə ˈsɪti hæz bɪˈkʌm ˈvɛri ɪkˈspɛnsɪv/', 'Particípio igual à base: "become". Mudança com efeito no presente.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"become","pos":"verb","ipa":"/bɪˈkʌm/","gloss":"tornar-se"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-15-05', 'lesson-essential-verbs-a1-15', 5, 'sentence', 'The bus leaves at eight.', 'O ônibus sai às oito.', '/ðə bʌs liːvz æt eɪt/', 'Presente simples para horário fixo, mesmo sendo futuro.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"leaves","pos":"verb","ipa":"/liːvz/","gloss":"sai, parte"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-15-06', 'lesson-essential-verbs-a1-15', 6, 'sentence', 'I left my bag at the hotel.', 'Deixei minha bolsa no hotel.', '/aɪ lɛft maɪ bæɡ æt ðə hoʊˈtɛl/', 'Passado irregular: "left". "Leave" = sair ou deixar algo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-15-07', 'lesson-essential-verbs-a1-15', 7, 'sentence', 'I''ll leave the door open.', 'Vou deixar a porta aberta.', '/aɪl liːv ðə dɔːr ˈoʊpən/', '"Leave" + objeto + adjetivo = deixar algo de certo jeito.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-15-08', 'lesson-essential-verbs-a1-15', 8, 'sentence', 'Has the train left yet?', 'O trem já saiu?', '/hæz ðə treɪn lɛft jɛt/', 'Present perfect + "yet" em pergunta = já.', '[]'::jsonb, '[{"surface":"Has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-16-01', 'lesson-essential-verbs-a1-16', 1, 'sentence', 'Put your phone on the table.', 'Coloque o celular na mesa.', '/pʊt jʊr foʊn ɑːn ðə ˈteɪbəl/', 'Imperativo com "put" (colocar). "On the table" = em cima da mesa.', '[]'::jsonb, '[{"surface":"Put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"table","pos":"noun","ipa":"/ˈteɪbəl/","gloss":"mesa"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-16-02', 'lesson-essential-verbs-a1-16', 2, 'sentence', 'I put the keys in my bag.', 'Coloquei as chaves na bolsa.', '/aɪ pʊt ðə kiːz ɪn maɪ bæɡ/', 'Passado e particípio iguais à base: put, put, put. O contexto mostra o tempo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-16-03', 'lesson-essential-verbs-a1-16', 3, 'sentence', 'I''ll put it in the fridge.', 'Vou colocar na geladeira.', '/aɪl pʊt ɪt ɪn ðə frɪdʒ/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"fridge","pos":"noun","ipa":"/frɪdʒ/","gloss":"geladeira"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-16-04', 'lesson-essential-verbs-a1-16', 4, 'sentence', 'She has put on some weight.', 'Ela engordou um pouco.', '/ʃiː hæz pʊt ɑːn sʌm weɪt/', '"Put on weight" = engordar. "Put on" também é vestir: "put on a coat".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"weight","pos":"noun","ipa":"/weɪt/","gloss":"peso"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-16-05', 'lesson-essential-verbs-a1-16', 5, 'sentence', 'What does this word mean?', 'O que significa esta palavra?', '/wʌt dʌz ðɪs wɜːrd miːn/', 'Pergunta essencial: "What does … mean?".', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"word","pos":"noun","ipa":"/wɜːrd/","gloss":"palavra"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-16-06', 'lesson-essential-verbs-a1-16', 6, 'sentence', 'Sorry, I didn''t mean that.', 'Desculpe, não foi isso que eu quis dizer.', '/ˈsɑːri aɪ ˈdɪdənt miːn ðæt/', 'Passado de "mean": "meant"; na negativa usa "didn''t mean".', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-16-07', 'lesson-essential-verbs-a1-16', 7, 'sentence', 'This will mean a lot to her.', 'Isso vai significar muito para ela.', '/ðɪs wɪl miːn ə lɑːt tuː hɜːr/', '"Mean a lot to" = ser importante para.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-16-08', 'lesson-essential-verbs-a1-16', 8, 'sentence', 'I''ve always meant to learn guitar.', 'Sempre tive a intenção de aprender violão.', '/aɪv ˈɔːlweɪz mɛnt tuː lɜːrn ɡɪˈtɑːr/', '"Mean to" = ter a intenção de. Particípio: "meant" /mɛnt/.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"meant","pos":"verb","ipa":"/mɛnt/","gloss":"quis dizer, significou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"learn","pos":"verb","ipa":"/lɜːrn/","gloss":"aprender"},{"surface":"guitar","pos":"noun","ipa":"/ɡɪˈtɑːr/","gloss":"violão, guitarra"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-17-01', 'lesson-essential-verbs-a1-17', 1, 'sentence', 'Keep the change.', 'Fique com o troco.', '/kiːp ðə tʃeɪndʒ/', '"Keep" = ficar com, guardar.', '[]'::jsonb, '[{"surface":"Keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-17-02', 'lesson-essential-verbs-a1-17', 2, 'sentence', 'She kept the receipt.', 'Ela guardou o recibo.', '/ʃiː kɛpt ðə rɪˈsiːt/', 'Passado irregular: "kept".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"kept","pos":"verb","ipa":"/kɛpt/","gloss":"guardou, manteve"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"receipt","pos":"noun","ipa":"/rɪˈsiːt/","gloss":"recibo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-17-03', 'lesson-essential-verbs-a1-17', 3, 'sentence', 'I will keep you posted.', 'Vou te mantendo informado.', '/aɪ wɪl kiːp juː ˈpoʊstɪd/', '"Keep someone posted" = manter alguém informado. Muito usado no trabalho.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"posted","pos":"adjective","ipa":"/ˈpoʊstɪd/","gloss":"informado (keep posted)"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-17-04', 'lesson-essential-verbs-a1-17', 4, 'sentence', 'I''ve kept all my old photos.', 'Guardei todas as minhas fotos antigas.', '/aɪv kɛpt ɔːl maɪ oʊld ˈfoʊtoʊz/', 'Present perfect: "have kept". Com "keep" + verbo em -ing o sentido é continuar: "keep trying".', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"kept","pos":"verb","ipa":"/kɛpt/","gloss":"guardou, manteve"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"photos","pos":"noun","ipa":"/ˈfoʊtoʊz/","gloss":"fotos"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-17-05', 'lesson-essential-verbs-a1-17', 5, 'sentence', 'Let me help you.', 'Deixa eu te ajudar.', '/lɛt miː hɛlp juː/', '"Let" + pessoa + verbo base: "let me help". Oferta educada.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-17-06', 'lesson-essential-verbs-a1-17', 6, 'sentence', 'My boss let me leave early.', 'Meu chefe me deixou sair cedo.', '/maɪ bɔːs lɛt miː liːv ˈɜːrli/', 'Passado igual à base: "let". O contexto mostra o tempo.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"boss","pos":"noun","ipa":"/bɔːs/","gloss":"chefe"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-17-07', 'lesson-essential-verbs-a1-17', 7, 'sentence', 'I''ll let you know.', 'Eu te aviso.', '/aɪl lɛt juː noʊ/', '"Let you know" = te avisar. Expressão muito comum.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-17-08', 'lesson-essential-verbs-a1-17', 8, 'sentence', 'Let''s go.', 'Vamos.', '/lɛts ɡoʊ/', '"Let''s" (let us) + verbo = vamos. Faz sugestões.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-18-01', 'lesson-essential-verbs-a1-18', 1, 'verb_forms', 'try tried tried', 'tentar, experimentar', '/traɪ traɪd traɪd/', 'Regular com "y" → "i": try, tried, tried.', '[]'::jsonb, '[{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"tried","pos":"verb","ipa":"/traɪd/","gloss":"tentou, experimentou"},{"surface":"tried","pos":"verb","ipa":"/traɪd/","gloss":"tentou, experimentou"}]'::jsonb, 'She tried the local food.', 'Ela experimentou a comida local.'),
  ('unit-essential-verbs-a1-18-02', 'lesson-essential-verbs-a1-18', 2, 'verb_forms', 'ask asked asked', 'perguntar, pedir', '/æsk æskt æskt/', 'Regular: "-ed" soa /t/.', '[]'::jsonb, '[{"surface":"ask","pos":"verb","ipa":"/æsk/","gloss":"perguntar, pedir"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"}]'::jsonb, 'He asked for the check.', 'Ele pediu a conta.'),
  ('unit-essential-verbs-a1-18-03', 'lesson-essential-verbs-a1-18', 3, 'verb_forms', 'need needed needed', 'precisar', '/niːd ˈniːdɪd ˈniːdɪd/', 'Regular: "-ed" soa /ɪd/ depois de "d".', '[]'::jsonb, '[{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"needed","pos":"verb","ipa":"/ˈniːdɪd/","gloss":"precisou"},{"surface":"needed","pos":"verb","ipa":"/ˈniːdɪd/","gloss":"precisou"}]'::jsonb, 'We needed more time.', 'Precisávamos de mais tempo.'),
  ('unit-essential-verbs-a1-18-04', 'lesson-essential-verbs-a1-18', 4, 'verb_forms', 'feel felt felt', 'sentir', '/fiːl fɛlt fɛlt/', 'Base "feel" · passado e particípio "felt".', '[]'::jsonb, '[{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"felt","pos":"verb","ipa":"/fɛlt/","gloss":"sentiu"},{"surface":"felt","pos":"verb","ipa":"/fɛlt/","gloss":"sentiu"}]'::jsonb, 'She felt sick after the trip.', 'Ela se sentiu mal depois da viagem.'),
  ('unit-essential-verbs-a1-18-05', 'lesson-essential-verbs-a1-18', 5, 'verb_forms', 'become became become', 'tornar-se', '/bɪˈkʌm bɪˈkeɪm bɪˈkʌm/', 'Base "become" · passado "became" · particípio "become".', '[]'::jsonb, '[{"surface":"become","pos":"verb","ipa":"/bɪˈkʌm/","gloss":"tornar-se"},{"surface":"became","pos":"verb","ipa":"/bɪˈkeɪm/","gloss":"tornou-se"},{"surface":"become","pos":"verb","ipa":"/bɪˈkʌm/","gloss":"tornar-se"}]'::jsonb, 'She became a doctor.', 'Ela se tornou médica.'),
  ('unit-essential-verbs-a1-18-06', 'lesson-essential-verbs-a1-18', 6, 'verb_forms', 'leave left left', 'sair, deixar', '/liːv lɛft lɛft/', 'Base "leave" · passado e particípio "left".', '[]'::jsonb, '[{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"}]'::jsonb, 'I left my bag at the hotel.', 'Deixei minha bolsa no hotel.'),
  ('unit-essential-verbs-a1-18-07', 'lesson-essential-verbs-a1-18', 7, 'verb_forms', 'put put put', 'colocar', '/pʊt pʊt pʊt/', 'As três formas são iguais.', '[]'::jsonb, '[{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"}]'::jsonb, 'I put the keys in my bag.', 'Coloquei as chaves na bolsa.'),
  ('unit-essential-verbs-a1-18-08', 'lesson-essential-verbs-a1-18', 8, 'verb_forms', 'mean meant meant', 'significar, querer dizer', '/miːn mɛnt mɛnt/', 'Base "mean" /miːn/ · passado e particípio "meant" /mɛnt/.', '[]'::jsonb, '[{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"meant","pos":"verb","ipa":"/mɛnt/","gloss":"quis dizer, significou"},{"surface":"meant","pos":"verb","ipa":"/mɛnt/","gloss":"quis dizer, significou"}]'::jsonb, 'Sorry, I didn''t mean that.', 'Desculpe, não foi isso que eu quis dizer.'),
  ('unit-essential-verbs-a1-18-09', 'lesson-essential-verbs-a1-18', 9, 'verb_forms', 'keep kept kept', 'manter, guardar', '/kiːp kɛpt kɛpt/', 'Base "keep" · passado e particípio "kept".', '[]'::jsonb, '[{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"kept","pos":"verb","ipa":"/kɛpt/","gloss":"guardou, manteve"},{"surface":"kept","pos":"verb","ipa":"/kɛpt/","gloss":"guardou, manteve"}]'::jsonb, 'She kept the receipt.', 'Ela guardou o recibo.'),
  ('unit-essential-verbs-a1-18-10', 'lesson-essential-verbs-a1-18', 10, 'verb_forms', 'let let let', 'deixar, permitir', '/lɛt lɛt lɛt/', 'As três formas são iguais.', '[]'::jsonb, '[{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"}]'::jsonb, 'My boss let me leave early.', 'Meu chefe me deixou sair cedo.')
